SELECT SAMPLE_MONTH, WARD_ID, WARD_NAME, PARAM_CODE, N_READINGS, N_MISSING, N_SENSOR_ONLY, N_LAB_VERIFIED, CASE WHEN (N_READINGS - N_MISSING) > 0 THEN ROUND(100.0 * (N_READINGS - N_MISSING) / N_READINGS, 2) END AS PCT_COMPLETE, CASE WHEN (N_READINGS - N_MISSING) > 0 THEN ROUND(100.0 * N_LAB_VERIFIED / (N_READINGS - N_MISSING), 2) END AS PCT_LAB FROM WARDQ.V_DATA_QUALITY WHERE N_MISSING > 0 ORDER BY PCT_COMPLETE, WARD_ID, PARAM_CODE LIMIT 200
